    name: { de: "Petrosawodsk", hu: "Petrozavodszk", ro: "Petrozavodsk", en: "Petrozavodsk"},
    image: "/poi-images/russia-petrozavodsk-cities-v2.webp",
    coords: [34.35, 61.7833],
